(() => {
  'use strict';
  const E = window.ClipaEngine, KEY = 'clipa-demo-v1', PREF = 'clipa-demo-ui-v1';
  const $ = (s, root = document) => root.querySelector(s);
  const h = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = n => '$' + (Number(n || 0) / 100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  const num = n => Number(n || 0).toLocaleString('es-CO');
  const compact = n => n >= 1000000 ? (n / 1000000).toFixed(1) + ' M' : n >= 1000 ? (n / 1000).toLocaleString('es-CO',{maximumFractionDigits:1}) + ' mil' : num(n);
  const date = n => new Date(n).toLocaleDateString('es-CO',{day:'numeric',month:'short',year:'numeric',timeZone:'America/Bogota'});
  const paths = {
    play:'<path d="m7 4 14 8-14 8Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    video:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 8 6 4-6 4Z"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2L5 5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h15V8H5a2 2 0 0 1 0-4"/><path d="M20 12h-6v5h6m-3-2.5h.1"/>',
    arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10m-9 13h6"/>',
    eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 2 8 3v6c0 6-8 11-8 11S4 17 4 11V5Z"/><path d="m8 11 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',chart:'<path d="M4 4v16h17M8 15v-4m5 4V6m5 9V9"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',folder:'<path d="M3 6h7l2 3h9v11H3Z"/>',bank:'<path d="m3 8 9-5 9 5ZM3 21h18M6 11v7m6-7v7m6-7v7"/>',
    close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 17V5m-5 5 5-5 5 5M4 17v4h16v-4"/>',link:'<path d="m10 14 4-4m-7 6-1 1a3 3 0 0 1-4-4l5-5a3 3 0 0 1 4 0m2 0 1-1a3 3 0 0 1 4 4l-5 5a3 3 0 0 1-4 0"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',pause:'<path d="M8 5v14M16 5v14"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M10 4H4v16h6m3-13 5 5-5 5m-5-5h12"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>'
  };
  const icon = name => '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">' + (paths[name] || paths.grid) + '</svg>';
  const statusNames = {draft:'Borrador',awaiting:'Esperando fondos',active:'Activa',paused:'Pausada',depleted:'Agotada',completed:'Completada',submitted:'Enviado',review:'En revisión',approved:'Aprobado',quarantined:'En cuarentena',rejected:'Rechazado',revoked:'Revocado',held:'En retención',frozen:'Congelado',available:'Disponible',processing:'Procesando',paid:'Pagado',reversed:'Revertido'};
  const badge = status => `<span class="badge ${h(status)}">${h(statusNames[status] || status)}</span>`;
  const cover = c => `assets/${({coffee:'coffee',sport:'sport',travel:'travel',music:'music'})[c.theme] || 'coffee'}.svg`;
  let storageOK = true, state, savedPrefs;
  try { const raw = JSON.parse(localStorage.getItem(KEY)); state = raw && raw.version === 1 && Array.isArray(raw.campaigns) && Array.isArray(raw.entries) ? E.settle(raw) : E.seed(); savedPrefs=JSON.parse(localStorage.getItem(PREF)); } catch { state=E.seed();storageOK=false; }
  const ui = {role:'creator',tab:'market',category:'Todas',search:'',sort:'featured',clipFilter:'all',reviewFilter:'pending',favorites:[],favoritesOnly:false,...savedPrefs};
  if(!['creator','brand','admin'].includes(ui.role))ui.role='creator';
  let toastTimer, lastFocus, modalState = null;
  const roles = {creator:{label:'Creador',name:'Sofía Torres',initial:'ST',caption:'Creadora de contenido',home:'market'},brand:{label:'Marca',name:'Estudio Norte',initial:'EN',caption:'Espacio de marcas',home:'campaigns'},admin:{label:'Administrador',name:'Equipo Clipa',initial:'CL',caption:'Administración',home:'review'}};
  const campaignById = id => state.campaigns.find(c=>c.id===id);
  const subById = id => state.submissions.find(v=>v.id===id);
  const ownVideos = () => state.submissions.filter(v=>v.creatorId===E.CREATOR);
  const btn = (label, action, cls='light', attrs='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
  const footer = () => `<footer class="bottom-note"><span>${icon('shield')} Entorno de demostración · Datos y movimientos ficticios</span><span>Hecho para crear. Diseñado para crecer. &nbsp; © Clipa 2026</span></footer>`;
  function persist(){
    try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(PREF,JSON.stringify({role:ui.role,tab:ui.tab,favorites:ui.favorites}));storageOK=true;}
    catch{storageOK=false;toast('El navegador no permite guardar. Los cambios durarán solo mientras esta pestaña esté abierta.',true);}
  }
  function commit(action,p={}){const outcome=E.execute(state,action,p);state=outcome.state;persist();return outcome.result;}
  function toast(message,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${icon(error?'info':'check')}<span>${h(message)}</span></div>`;toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',5500);}
  function stat(label,value,note,ico,positive=false){return `<div class="stat"><div class="stat-top"><span>${label}</span>${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-note ${positive?'positive':''}">${note}</div></div>`;}
  function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
  function empty(title,description,button=''){return `<div class="empty">${icon('folder')}<h3>${title}</h3><p>${description}</p>${button}</div>`;}
  function navigate(tab,role=ui.role){ui.role=role;ui.tab=tab;ui.search='';closeModal();persist();render();window.scrollTo({top:0,behavior:'instant'});}
  function render(){
    const r=roles[ui.role],pending=state.submissions.filter(v=>['submitted','review','quarantined'].includes(v.status)).length;
    const nav=ui.role==='creator'?[['market','grid','Explorar campañas'],['clips','video','Mis clips',ownVideos().length],['wallet','wallet','Mi billetera']]:ui.role==='brand'?[['campaigns','grid','Mis campañas'],['results','chart','Resultados']]:[['review','shield','Revisar clips',pending],['funds','bank','Fondeo de campañas',state.campaigns.filter(c=>c.status==='awaiting').length],['payments','wallet','Pagos a creadores',state.payouts.filter(p=>p.status==='processing').length]];
    if(!nav.some(n=>n[0]===ui.tab)&&ui.tab!=='demo')ui.tab=r.home;
    const pageName=ui.tab==='demo'?'Cómo funciona':nav.find(n=>n[0]===ui.tab)?.[2];
    $('#app').innerHTML=`<div class="mobile-overlay" data-action="menu-close"></div><aside class="sidebar" aria-label="Navegación principal"><button class="logo" data-action="home" aria-label="Clipa, inicio"><span class="logo-mark">${icon('play')}</span>clipa<span style="color:var(--accent)">.</span></button><div class="logo-tag">Create. Clip. Earn.</div><div class="workspace-label">Tu espacio · ${r.label}</div><nav class="nav-list">${nav.map(([key,ico,label,count])=>`<button class="nav-item ${ui.tab===key?'active':''}" data-action="nav" data-tab="${key}" ${ui.tab===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${count?`<span class="count">${count}</span>`:''}</button>`).join('')}</nav><div class="sidebar-spacer"></div><div class="guide-card"><div class="tiny">DE LA IDEA AL INGRESO</div><h3>Tu creatividad.<br>Todo un recorrido.</h3><p>Descubre cómo una historia se convierte en una oportunidad.</p><button data-action="nav" data-tab="demo">Cómo funciona ${icon('arrow')}</button></div><button class="nav-item ${ui.tab==='demo'?'active':''}" data-action="nav" data-tab="demo">${icon('spark')}Explorar la demo</button><div class="sidebar-footer"><div class="avatar ${ui.role}">${r.initial}</div><div><div class="person-name">${r.name}</div><div class="person-caption">${r.caption}</div></div>${icon('down')}</div></aside><div class="app-body"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir navegación">${icon('menu')}</button><div class="breadcrumb"><span>Mi espacio</span>${icon('chevron')}<span>${pageName}</span></div><div class="top-actions"><span class="local-dot">Demo local</span><div class="role-control"><label for="role-select">Vista de</label><select id="role-select" aria-label="Cambiar perfil de la demo">${Object.entries(roles).map(([key,role])=>`<option value="${key}" ${key===ui.role?'selected':''}>${role.label}</option>`).join('')}</select></div><button class="icon-btn" aria-label="Ver notificaciones" data-action="notifications">${icon('bell')}<i class="notif-dot"></i></button></div></header><main class="content" id="main">${!storageOK?'<div class="info-banner warning"><p>El guardado local no está disponible. Mantén esta pestaña abierta para conservar la sesión.</p></div>':''}${({market:market,clips:clips,wallet:walletPage,campaigns:brandCampaigns,results:resultsPage,review:reviewPage,funds:fundsPage,payments:paymentsPage,demo:demoPage})[ui.tab]()}${footer()}</main></div>`;
  }
  function campaignCard(c){
    const available=c.budget-c.spent,clips=state.submissions.filter(v=>v.campaignId===c.id).length;
    return `<article class="campaign-card"><div class="campaign-cover"><img src="${cover(c)}" alt="Universo visual de ${h(c.brand)}" loading="lazy"><span class="cover-tag">${h(c.category)}</span><button class="save-btn ${ui.favorites.includes(c.id)?'saved':''}" data-action="favorite" data-id="${c.id}" aria-label="${ui.favorites.includes(c.id)?'Quitar de':'Añadir a'} guardadas: ${h(c.brand)}" aria-pressed="${ui.favorites.includes(c.id)}">${icon('bookmark')}</button></div><div class="campaign-body"><div class="brand-row"><span class="brand-dot">${h(c.brand[0])}</span>${h(c.brand)}<span class="small-icon brand-check">${icon('shield')}</span></div><h3 class="campaign-title">${h(c.title)}</h3><div class="platforms"><span>TikTok</span><span>Reels</span><span>Shorts</span></div><div class="cpm-line"><strong>${money(c.cpm)}</strong><span>USD / 1.000 visualizaciones</span></div><div class="progress" aria-label="${Math.round(available/c.budget*100)} por ciento de presupuesto disponible"><i style="width:${available/c.budget*100}%"></i></div><div class="budget-caption"><b>${money(available)} disponibles</b><span>de ${money(c.budget)}</span></div><div class="campaign-bottom"><span class="small">${clips?num(clips)+(clips===1?' clip enviado':' clips enviados'):'Sé de los primeros'}</span><button class="text-btn" data-action="campaign-detail" data-id="${c.id}">Ver campaña ${icon('arrow')}</button></div></div></article>`;
  }
  function filteredCampaigns(){let list=state.campaigns.filter(c=>c.status==='active'&&c.spent<c.budget);if(ui.category!=='Todas')list=list.filter(c=>c.category===ui.category);if(ui.favoritesOnly)list=list.filter(c=>ui.favorites.includes(c.id));const q=ui.search.toLocaleLowerCase('es');if(q)list=list.filter(c=>(c.title+' '+c.brand+' '+c.category).toLocaleLowerCase('es').includes(q));if(ui.sort==='cpm')list.sort((a,b)=>b.cpm-a.cpm);if(ui.sort==='budget')list.sort((a,b)=>(b.budget-b.spent)-(a.budget-a.spent));return list;}
  function gridHtml(){const list=filteredCampaigns();return list.length?list.map(campaignCard).join(''):empty('Aquí empieza otra búsqueda.','Prueba con otra categoría o vuelve a ver todas las campañas.',btn('Limpiar filtros','clear-filters','soft'));}
  function market(){
    const w=E.wallet(state),own=ownVideos(),views=own.filter(v=>v.status==='approved').reduce((n,v)=>n+v.views,0);
    return heading('Un buen día para crear','Tu próximo clip empieza aquí.','Conecta con marcas que van contigo. Crea a tu manera.',btn(icon('video')+'<span>Mis clips</span>','nav','light','data-tab="clips" aria-label="Mis clips"'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('spark')} HECHO PARA TU CREATIVIDAD</div><h2>Grandes historias.<br><em>Pequeños clips.</em></h2><p>Encuentra una campaña, dale tu toque y gana por cada mil visualizaciones verificadas.</p><button class="btn dark" data-action="scroll-campaigns">Encuentra tu campaña ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit"></div><span class="art-label">TU TALENTO, EN MOVIMIENTO</span><div class="mini-poster"><img src="assets/coffee.svg" alt=""><span class="poster-play">${icon('play')}</span></div><div class="mini-poster second"><img src="assets/sport.svg" alt=""><span class="poster-play">${icon('play')}</span></div><span class="art-star">✳</span><div class="art-pill">${icon('chart')} Una buena historia <strong>sí cuenta ↗</strong></div></div></section><div class="stats-grid">${stat('Ganancias acumuladas',money(w.total)+'<small>USD</small>','Tus clips ya están dando frutos','chart',true)}${stat('Saldo disponible',money(w.available)+'<small>USD</small>','Listo para tu próximo retiro','wallet')}${stat('En retención',money(w.pending)+'<small>USD</small>','Protegido durante 14 días','clock')}${stat('Visualizaciones verificadas',compact(views),'En '+own.filter(v=>v.status==='approved').length+' clips aprobados','eye',true)}</div><section id="campaigns-section"><div class="section-heading"><div><h2>Encuentra tu próxima historia</h2><p>Marcas con algo que contar. Creadores con algo que aportar.</p></div><span class="small muted"><span id="campaign-count">${filteredCampaigns().length}</span> campañas</span></div><div class="market-tools"><div class="filters">${['Todas','Gastronomía','Lifestyle','Viajes','Música'].map(cat=>`<button class="chip ${ui.category===cat?'active':''}" data-action="category" data-category="${cat}" aria-pressed="${ui.category===cat}">${cat}</button>`).join('')}<button class="chip small-icon ${ui.favoritesOnly?'active':''}" data-action="favorites-filter" aria-label="Solo campañas guardadas" aria-pressed="${ui.favoritesOnly}">${icon('bookmark')}</button></div><label class="search">${icon('search')}<input id="market-search" type="search" placeholder="Busca una marca o campaña" value="${h(ui.search)}" aria-label="Buscar campañas"></label></div><div class="campaign-grid" id="campaign-grid">${gridHtml()}</div></section>`;
  }
  function clips(){
    const own=ownVideos(),q=own.filter(v=>v.status==='quarantined'),list=ui.clipFilter==='all'?own:own.filter(v=>ui.clipFilter==='pending'?['submitted','review','quarantined'].includes(v.status):v.status===ui.clipFilter);
    return heading('Tu estudio','Cada clip tiene una historia.','Sigue tus envíos, revisiones y ganancias en un mismo lugar.',btn(icon('plus')+'Explorar campañas','nav','primary','data-tab="market"'))+(q.length?`<div class="info-banner warning">${icon('shield')}<p><strong>${q.length} clip necesita tus analíticas.</strong> Adjunta una grabación de pantalla para continuar la revisión. Tienes 48 horas desde la alerta.</p></div>`:'')+`<div class="filters mb">${[['all','Todos los clips'],['pending','Por revisar'],['approved','Aprobados'],['rejected','Rechazados']].map(([val,label])=>`<button class="chip ${ui.clipFilter===val?'active':''}" data-action="clip-filter" data-value="${val}">${label}</button>`).join('')}</div><div class="panel">${list.length?`<div class="table-wrap"><table><thead><tr><th>Tu clip / Campaña</th><th>Estado</th><th>Vistas verificadas</th><th>Ganancias</th><th></th></tr></thead><tbody>${list.map(v=>{const c=campaignById(v.campaignId);return `<tr><td><div class="table-title"><img class="table-thumb" src="${cover(c)}" alt=""><div><strong>${h(v.title)}</strong><p>${h(c.brand)} · ${v.platform}</p></div></div></td><td>${badge(v.status)}</td><td>${v.status==='approved'?num(v.views):'—'}</td><td>${money(v.earned)} <span class="tiny muted">USD</span></td><td>${btn(v.status==='quarantined'?'Ver alerta':'Ver detalle','clip-detail','light sm',`data-id="${v.id}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Todavía no hay clips aquí.','Elige una campaña y envía tu primer enlace.',btn('Explorar campañas','nav','soft','data-tab="market"'))}</div><div class="info-banner mt">${icon('info')}<p>Las visualizaciones se verifican manualmente. Cada 48 horas, el equipo puede actualizar el conteo de tus clips aprobados.</p></div>`;
  }
  function walletPage(){
    const w=E.wallet(state),entries=state.entries.filter(e=>e.creatorId===E.CREATOR).slice().sort((a,b)=>b.createdAt-a.createdAt),payouts=state.payouts.filter(p=>p.creatorId===E.CREATOR);
    return heading('Tu creatividad tiene valor','Mi billetera','Aquí puedes seguir cada ingreso, desde la aprobación hasta el pago.',`<span class="demo-top">${icon('clock')}Fecha de demo: ${date(state.now)}</span>`)+`<div class="two-col"><div class="wallet-main"><div class="label">Disponible para retirar</div><div class="balance">${money(w.available)} <small>USD</small></div>${btn(icon('arrow')+'Solicitar retiro','withdraw','dark',w.available?'':'disabled')}<p class="wallet-note">Pagos programados el 1 y el 15 de cada mes.</p></div><div class="panel account-box"><div class="eyebrow">Destino de tus pagos</div><h3>${h(state.creator.method)}</h3><p>${h(state.creator.name)}</p><p>${h(state.creator.account)}</p>${btn('Editar cuenta de ejemplo','account','light sm')}<p class="tiny muted" style="margin-top:12px">Usa únicamente datos ficticios en esta demo.</p></div></div><div class="metric-row">${stat('En retención',money(w.pending),'Cada abono se libera después de 14 días','clock')}${stat('Retiros en proceso',money(w.processing),'Reservado hasta completar el pago','bank')}${stat('Total pagado',money(w.paid),'Historial de pagos completados','check')}</div><div class="panel"><div class="panel-title"><div><h2>Actividad de tu billetera</h2><p>Cada movimiento tiene una historia detrás.</p></div><span class="badge">USD</span></div>${entries.length?`<div class="table-wrap"><table><thead><tr><th>Concepto</th><th>Ingreso</th><th>Estado</th><th>Liberación</th></tr></thead><tbody>${entries.map(e=>{const v=subById(e.submissionId);return `<tr><td><strong>${h(v.title)}</strong><p>${h(campaignById(e.campaignId).brand)} · ${date(e.createdAt)}</p></td><td>${money(e.amount)}</td><td>${badge(e.status)}</td><td>${e.status==='frozen'?'Requiere revisión':e.status==='reversed'?'Devuelto a la campaña':date(e.releaseAt)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Tus primeras ganancias están por llegar.','Envía un clip para empezar.')}</div><div class="panel mt"><div class="panel-title"><h2>Mis retiros</h2></div>${payouts.length?`<div class="table-wrap"><table><thead><tr><th>Solicitud</th><th>Monto</th><th>Estado</th><th></th></tr></thead><tbody>${payouts.map(p=>`<tr><td>${date(p.createdAt)}<p>${h(p.method)} · ${h(p.account)}</p></td><td>${money(p.amount)}</td><td>${badge(p.status)}</td><td>${p.status==='paid'?btn('Ver comprobante','receipt','light sm',`data-id="${p.id}"`):'<span class="tiny muted">En cola de pagos</span>'}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no has solicitado un retiro.','Cuando tengas saldo disponible, podrás enviarlo a tu cuenta de ejemplo.')}</div>`;
  }
  function brandCampaigns(){
    const active=state.campaigns.filter(c=>c.status==='active').length,budget=state.campaigns.filter(c=>c.received>0).reduce((sum,c)=>sum+c.budget,0),spent=state.campaigns.reduce((sum,c)=>sum+c.spent,0),approved=state.submissions.filter(v=>v.status==='approved');
    return heading('Estudio Norte · Portal de marcas','Historias que hacen crecer tu marca.','Crea campañas y conecta con una nueva generación de creadores.',btn(icon('plus')+'Crear campaña','new-campaign','primary'))+`<div class="stats-grid">${stat('Campañas activas',active,'Abiertas a nuevos creadores','grid',true)}${stat('Presupuesto fondeado',money(budget),'Fondos confirmados por administración','bank')}${stat('Inversión verificada',money(spent),'Asignada a clips aprobados','chart')}${stat('Alcance verificado',compact(approved.reduce((n,v)=>n+v.views,0)),approved.length+' clips aprobados','eye',true)}</div><div class="panel"><div class="panel-title"><div><h2>Tus campañas</h2><p>De una buena idea a miles de nuevas miradas.</p></div><span class="small muted">${state.campaigns.length} campañas</span></div><div class="table-wrap"><table><thead><tr><th>Campaña</th><th>Estado</th><th>Presupuesto</th><th>Invertido</th><th>Tarifa / 1.000</th><th></th></tr></thead><tbody>${state.campaigns.map(c=>`<tr><td><div class="table-title"><img class="table-thumb" src="${cover(c)}" alt=""><div><strong>${h(c.title)}</strong><p>${h(c.brand)} · ${h(c.category)}</p></div></div></td><td>${badge(c.status)}</td><td>${money(c.budget)}</td><td>${money(c.spent)}</td><td>${money(c.cpm)}</td><td>${btn(c.status==='draft'?'Editar borrador':c.status==='awaiting'?'Ver fondeo':'Administrar','manage-campaign','light sm',`data-id="${c.id}"`)}</td></tr>`).join('')}</tbody></table></div></div><div class="info-banner mt">${icon('shield')}<p><strong>El control comienza antes de publicar.</strong> Tu campaña solo aparece para los creadores después de que administración confirma el depósito.</p></div>`;
  }
  function resultsPage(){
    const approved=state.submissions.filter(v=>v.status==='approved'),views=approved.reduce((s,v)=>s+v.views,0),spent=state.campaigns.reduce((s,c)=>s+c.spent,0),funded=state.campaigns.filter(c=>c.received>0),max=Math.max(1,...funded.map(c=>state.submissions.filter(v=>v.campaignId===c.id&&v.status==='approved').reduce((s,v)=>s+v.views,0)));
    return heading('Lo que cuentan los números','Tu impacto, en perspectiva.','Resultados calculados con las auditorías de los clips de esta demo.',btn(icon('download')+'Exportar resultados','export-results','light'))+`<div class="stats-grid">${stat('Alcance verificado',compact(views),'Visualizaciones auditadas','eye',true)}${stat('Inversión en clips',money(spent),'Descontada del presupuesto','chart')}${stat('Clips aprobados',approved.length,'Contenido que cumple tus reglas','video')}${stat('CPM efectivo',money(views?Math.round(spent/views*1000):0),'Inversión / vistas verificadas × 1.000','spark')}</div><div class="two-col"><section class="panel panel-pad"><h2>Alcance por campaña</h2><p class="small mt">Visualizaciones verificadas, acumuladas.</p><div class="chart">${funded.map(c=>{const n=approved.filter(v=>v.campaignId===c.id).reduce((s,v)=>s+v.views,0);return `<div class="bar-group"><span class="bar-value">${compact(n)}</span><div class="bar" style="height:${Math.max(1,n/max*130)}px"></div></div>`;}).join('')}</div><div class="bar-labels">${funded.map(c=>`<span>${h(c.brand)}</span>`).join('')}</div></section><section class="panel panel-pad"><h2>De envío a aprobación</h2><p class="small mt">Estado actual de todos los clips.</p><div class="funnel">${[['Enviados',state.submissions.length],['Por revisar',state.submissions.filter(v=>['submitted','review'].includes(v.status)).length],['En cuarentena',state.submissions.filter(v=>v.status==='quarantined').length],['Aprobados',approved.length]].map(([label,n])=>`<div class="funnel-row"><span>${label}</span><div class="progress"><i style="width:${n/Math.max(state.submissions.length,1)*100}%"></i></div><strong>${n}</strong></div>`).join('')}</div></section></div><div class="panel panel-pad mt"><h2>Actividad reciente</h2>${eventsHtml(state.events.filter(e=>['all','brand'].includes(e.role)).slice(0,6))}</div>`;
  }
  function reviewPage(){
    const counts=state.submissions.filter(v=>['submitted','review'].includes(v.status)).length,quar=state.submissions.filter(v=>v.status==='quarantined').length;
    const list=state.submissions.filter(v=>ui.reviewFilter==='pending'?['submitted','review','quarantined'].includes(v.status):ui.reviewFilter==='approved'?v.status==='approved':['rejected','revoked'].includes(v.status));
    return heading('Centro de control','Cada vista cuenta. Cada revisión también.','Verifica el contenido, protege a las marcas y reconoce el trabajo de los creadores.',`<span class="demo-top">${icon('clock')}${date(state.now)}</span>`)+`<div class="stats-grid">${stat('Por revisar',counts,'En espera de una auditoría manual','video')}${stat('En cuarentena',quar,'Analíticas pendientes de verificación','shield')}${stat('Clips aprobados',state.submissions.filter(v=>v.status==='approved').length,'Conteos actualizables cada 48 horas','check')}${stat('Fondos retenidos',money(state.entries.filter(e=>['held','frozen'].includes(e.status)).reduce((n,e)=>n+e.amount,0)),'Periodo de seguridad de 14 días','clock')}</div><div class="section-heading"><h2>Cola de revisión</h2><div class="filters">${[['pending','Pendientes'],['approved','Aprobados'],['closed','Cerrados']].map(([key,label])=>`<button class="chip ${ui.reviewFilter===key?'active':''}" data-action="review-filter" data-value="${key}">${label}</button>`).join('')}</div></div><div class="review-grid">${list.length?list.map(v=>{const c=campaignById(v.campaignId),overdue=v.status==='quarantined'&&state.now>v.quarantinedAt+2*E.DAY;return `<article class="panel review-card"><div class="flex spread">${badge(v.status)}<span class="tiny muted">${date(v.createdAt)}</span></div><h3>${h(v.title)}</h3><div class="meta">${h(v.creatorName)} · ${h(c.brand)} · ${v.platform}</div><div class="review-preview"><img src="${cover(c)}" alt="Visual ilustrativo de ${h(c.brand)}"><span class="poster-play">${icon('play')}</span></div><div class="review-info"><span>${v.status==='quarantined'?(v.evidence?'Analíticas recibidas':overdue?'Plazo de 48 h vencido':'Esperando analíticas'):v.status==='approved'?num(v.views)+' vistas verificadas':'Nuevo contenido por verificar'}</span><strong>${money(v.earned)}</strong></div>${btn(v.status==='approved'?'Actualizar auditoría':['rejected','revoked'].includes(v.status)?'Ver decisión':'Revisar clip','review-detail','dark',`data-id="${v.id}"`)}</article>`;}).join(''):empty('La cola está al día.','Los nuevos envíos aparecerán aquí automáticamente.')}</div>`;
  }
  function fundsPage(){
    const list=state.campaigns.filter(c=>c.status==='awaiting'),paused=state.campaigns.filter(c=>c.status==='paused');
    return heading('Entrada de fondos','El inicio de cada oportunidad.','Confirma los depósitos simulados y publica las campañas en el marketplace.')+`<div class="info-banner">${icon('info')}<p><strong>Verificación manual.</strong> No se consulta ningún banco. Confirmar un depósito modifica únicamente los datos de esta demostración.</p></div><div class="panel"><div class="panel-title"><h2>Depósitos por verificar</h2><span class="badge awaiting">${list.length} pendientes</span></div>${list.length?list.map(c=>`<div class="funding-card"><img src="${cover(c)}" alt=""><div class="funding-copy"><h3>${h(c.title)}</h3><p>${h(c.brand)} · Referencia ${h(c.reference)}</p><div style="margin-top:9px">${badge(c.status)}</div></div><div class="funding-amount"><strong>${money(c.budget)}</strong>${btn('Verificar depósito','verify-funds','primary sm',`data-id="${c.id}"`)}</div></div>`).join(''):empty('Todos los depósitos están al día.','Las campañas enviadas por las marcas aparecerán aquí.')}</div>${paused.length?`<div class="panel mt"><div class="panel-title"><h2>Campañas pausadas</h2></div>${paused.map(c=>`<div class="funding-card"><div class="funding-copy"><h3>${h(c.title)}</h3><p>${money(c.budget-c.spent)} disponibles</p></div>${btn('Reanudar campaña','resume','soft',`data-id="${c.id}"`)}</div>`).join('')}</div>`:''}`;
  }
  function paymentsPage(){
    return heading('Salida de fondos','Un buen trabajo merece su pago.','Revisa los retiros, confirma los clips y adjunta el comprobante de ejemplo.')+`<div class="info-banner">${icon('bank')}<p><strong>Calendario de pagos: días 1 y 15.</strong> La demo permite simular el pago cualquier día para mostrar el recorrido completo. No se ejecutan transferencias ni se envían correos.</p></div><div class="panel"><div class="panel-title"><h2>Solicitudes de retiro</h2><span class="small muted">${state.payouts.filter(p=>p.status==='processing').length} por procesar</span></div>${state.payouts.length?`<div class="table-wrap"><table><thead><tr><th>Creador</th><th>Destino ficticio</th><th>Monto</th><th>Estado</th><th></th></tr></thead><tbody>${state.payouts.map(p=>`<tr><td><strong>${h(p.creatorName)}</strong><p>${date(p.createdAt)}</p></td><td>${h(p.method)}<p>${h(p.account)}</p></td><td>${money(p.amount)}</td><td>${badge(p.status)}</td><td>${btn(p.status==='paid'?'Ver comprobante':'Procesar pago',p.status==='paid'?'receipt':'process-payout',p.status==='paid'?'light sm':'primary sm',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay retiros pendientes.','Desde la vista de creador, solicita un retiro con el saldo disponible.',btn('Ir a la billetera del creador','go-creator-wallet','soft'))}</div>`;
  }
  function eventsHtml(events){return events.length?`<ul class="list-events">${events.map(e=>`<li><span class="event-point"></span><div>${h(e.message)}<small>${date(e.at)}</small></div></li>`).join('')}</ul>`:'<p class="small mt">Aquí aparecerán las próximas novedades.</p>';}
  function demoPage(){
    return heading('La idea, en acción','De una campaña a un ingreso.','Una plataforma para marcas, creadores y el equipo que conecta ambos mundos.',`<span class="demo-top">${icon('shield')}100% local · Sin servicios de pago</span>`)+`<div class="flow-grid">${[
      ['01','La marca propone.','Define el presupuesto, la tarifa por mil vistas y las reglas. El administrador verifica el depósito y activa la campaña.','Abrir campañas','go-brand'],
      ['02','El creador le da vida.','Explora campañas, consulta el material, edita su clip y envía el enlace publicado. El sistema evita duplicados.','Explorar campañas','go-market'],
      ['03','El equipo verifica.','Revisa las reglas y las interacciones. Aprueba el conteo, pide analíticas si hay dudas o rechaza el clip.','Ir a revisión','go-admin'],
      ['04','La creatividad cobra.','Después de 14 días, el saldo queda disponible. El creador solicita un retiro y el administrador registra el pago.','Abrir billetera','go-creator-wallet']
    ].map(([n,title,desc,label,action])=>`<article class="flow-step"><div class="step-num">${n}</div><h3>${title}</h3><p>${desc}</p>${btn(label+' '+icon('arrow'),action,'soft sm')}</article>`).join('')}</div><div class="clock-card"><div><div class="eyebrow" style="color:var(--acid)">El tiempo, a tu ritmo</div><h3>${date(state.now)}</h3><p>Avanza el reloj para demostrar las auditorías y la liberación de fondos.</p></div><div class="flex">${btn('+2 días','advance','light','data-days="2"')}${btn('+14 días','advance','light','data-days="14"')}${btn(icon('refresh')+'Reiniciar demo','reset-modal','light')}</div></div><div class="decisions"><div class="panel panel-pad"><h3>Lo que puedes mostrar al cliente</h3><p>Cambio entre los tres perfiles, creación y fondeo de campañas, envío y validación de enlaces, auditorías, cuarentena con pruebas, reversión de ganancias, billetera, retiros y comprobantes. Cada acción actualiza las otras vistas.</p><div class="state-chain">${badge('awaiting')}${icon('arrow')}${badge('active')}${icon('arrow')}${badge('depleted')}${icon('arrow')}${badge('completed')}</div></div><div class="panel panel-pad"><h3>Cómo está simulada esta versión</h3><p>Todos los valores están en USD ficticios y se guardan en este navegador. Las marcas, cuentas y clips son ejemplos. No hay autenticación, conexión con redes, Google Drive, bancos ni correo. Los archivos adjuntos conservan solo su nombre; puedes usar los ejemplos incluidos.</p></div><div class="panel panel-pad"><h3>Dos decisiones para esta propuesta</h3><p><strong>Retención por abono:</strong> los 14 días comienzan con cada aprobación o incremento. Los montos nuevos no heredan la antigüedad de otros.<br><strong>Una sola tarifa:</strong> el importe descontado a la marca es el que gana el creador. La comisión de plataforma queda por definir.</p></div><div class="panel panel-pad"><h3>Un recorrido listo para presentar</h3><p>1. Crea y activa una campaña.<br>2. Envía un clip con un enlace de ejemplo.<br>3. Apruébalo y revisa ambas billeteras.<br>4. Avanza 14 días, solicita el retiro y registra el pago.<br>También hay un clip en cuarentena para mostrar cómo se resuelve.</p></div></div><div class="panel panel-pad mt"><h2>Bitácora de la demostración</h2>${eventsHtml(state.events.slice(0,8))}</div>`;
  }
  function modal(title,subtitle,content,footerHtml='',wide=false){
    if(!$('#modal-root').innerHTML)lastFocus=document.activeElement;
    $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="close-btn" data-action="close" aria-label="Cerrar ventana">${icon('close')}</button></header><div class="modal-content">${content}</div>${footerHtml?`<footer class="modal-footer">${footerHtml}</footer>`:''}</section></div>`;
    document.body.style.overflow='hidden';$('.modal').focus();
  }
  function closeModal(){
    $('#modal-root').innerHTML='';document.body.style.overflow='';modalState=null;
    if(lastFocus?.isConnected)lastFocus.focus();
  }
  const formError = () => '<div class="form-error" id="form-error" role="alert"></div>';
  function field(label,name,value='',type='text',options=''){return `<div class="field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${h(value)}" ${options}></div>`;}
  const submitButton = (label,form,cls='primary') => `<button class="btn ${cls}" type="submit" form="${form}">${label}</button>`;
  function showCampaign(id){
    const c=campaignById(id);modalState={type:'campaign',id};
    modal(h(c.title),'Una historia de '+h(c.brand),`<img class="detail-cover" src="${cover(c)}" alt="Concepto visual de ${h(c.brand)}"><div class="detail-top"><div class="brand-row"><span class="brand-dot">${h(c.brand[0])}</span>${h(c.brand)} · ${h(c.category)}</div>${badge(c.status)}</div><p class="detail-description">${h(c.description)}</p><div class="detail-metrics"><div><span>Por 1.000 visualizaciones</span><strong>${money(c.cpm)}</strong></div><div><span>Presupuesto disponible</span><strong>${money(c.budget-c.spent)}</strong></div><div><span>Máximo por clip</span><strong>${money(c.maxPerVideo)}</strong></div></div><div class="rules"><h3>El brief creativo</h3><p>${h(c.rules)}</p><p style="margin-top:10px">Mínimo para generar ganancias: <strong>${num(c.minViews)} visualizaciones.</strong></p></div><div class="flex spread wrap"><span class="small muted">${icon('folder')} Material y referencias de la marca</span>${btn(icon('folder')+'Ver kit creativo','material','light sm',`data-id="${c.id}"`)}</div><div class="info-banner mt">${icon('shield')}<p>Publica tu clip, comparte el enlace y recibe ganancias por las vistas que apruebe el equipo. Cada abono tiene 14 días de retención.</p></div>`,btn('Cerrar','close','light')+btn('Enviar mi clip '+icon('arrow'),'submit-modal','primary',`data-id="${c.id}" ${c.status==='active'?'':'disabled'}`));
  }
  function showMaterial(id){const c=campaignById(id);modalState={type:'material',id};modal('Tu punto de partida','Kit creativo de ejemplo · '+h(c.brand),`<img class="detail-cover" src="${cover(c)}" alt="Material gráfico de ejemplo"><div class="rules"><h3>Una idea para tu clip</h3><p>0–3 s: abre con una pregunta o un detalle inesperado.\n3–15 s: presenta el producto o la experiencia con tu estilo.\n15–25 s: cierra con una idea memorable y el hashtag de la marca.</p></div><div class="info-banner">${icon('info')}<p>Este kit contiene un visual SVG y un brief descargables. Representa el material de Google Drive; no consulta enlaces externos ni contiene videos de producción.</p></div><div class="field"><label>Enlace de Drive registrado</label><div class="review-link">${h(c.drive)}</div></div>`,btn('Volver a campaña','campaign-detail','light',`data-id="${id}"`)+btn(icon('download')+'Visual SVG','download-visual','soft',`data-id="${id}"`)+btn(icon('download')+'Brief creativo','download-brief','primary',`data-id="${id}"`));}
  function showSubmit(id){const c=campaignById(id);modalState={type:'submit',id};modal('Una nueva historia, lista para salir.','Envía tu clip para '+h(c.brand),`<form id="submit-video" data-form="video" data-id="${id}"><div class="form-grid">${field('Título del clip','title','','text','required maxlength="100" placeholder="Ej. Mi ritual de cada mañana"')}<div class="field"><label>Campaña</label><input value="${h(c.brand)} · ${money(c.cpm)} / 1.000" disabled></div><div class="field full"><label for="video-url">Enlace público del video</label><input id="video-url" name="url" type="url" required placeholder="https://www.tiktok.com/@usuario/video/…"><small>TikTok, Instagram Reels o YouTube Shorts. Eliminamos el rastreo y comprobamos duplicados.</small></div></div><div class="flex mt">${btn(icon('spark')+'Usar enlace de ejemplo','example-link','soft sm')}</div><label class="check-field"><input type="checkbox" required name="rules"><span>Mi clip sigue las reglas de la campaña y utiliza material autorizado.</span></label>${formError()}</form><div class="info-banner mt">${icon('info')}<p>El enlace de ejemplo permite probar el envío sin publicar nada. Las visualizaciones se introducirán en la vista de administrador.</p></div>`,btn('Volver','campaign-detail','light',`data-id="${id}"`)+submitButton('Enviar a revisión '+icon('arrow'),'submit-video'));}
  function showCampaignForm(id){
    const c=id?campaignById(id):null;modalState={type:'campaign-form',id};
    modal(c?'Dale forma a tu borrador.':'Una gran campaña empieza aquí.','Define la propuesta. Los fondos se verificarán antes de publicarla.',`<form id="campaign-form" data-form="campaign" ${id?`data-id="${id}"`:''}><div class="form-grid">${field('Nombre de la campaña','title',c?.title||'','text','required maxlength="100" placeholder="Una historia que vale la pena contar"')}${field('Marca','brand',c?.brand||'','text','required maxlength="40" placeholder="Nombre de tu marca"')}<div class="field"><label for="category-field">Categoría</label><select id="category-field" name="category">${['Gastronomía','Lifestyle','Viajes','Música','Salud','Finanzas'].map(x=>`<option ${c?.category===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Presupuesto total (USD ficticios)','budget',c?c.budget/100:1000,'number','min="0.01" step="0.01" max="1000000" required')}${field('Pago por 1.000 visualizaciones (USD)','cpm',c?c.cpm/100:2.5,'number','min="0.01" step="0.01" max="1000000" required')}${field('Mínimo de visualizaciones por clip','minViews',c?.minViews||1000,'number','min="1" max="1000000000" step="1" required')}${field('Ganancia máxima por clip (USD)','maxPerVideo',c?c.maxPerVideo/100:250,'number','min="0.01" step="0.01" max="1000000" required')}${field('Carpeta de Google Drive','drive',c?.drive||'https://drive.google.com/drive/folders/demo-clipa','url','required')}<div class="field full"><label for="description-field">La idea en una frase</label><input id="description-field" name="description" maxlength="400" value="${h(c?.description||'')}" placeholder="¿Qué historia quieres contar con los creadores?"></div><div class="field full"><label for="rules-field">Instrucciones para los creadores</label><textarea id="rules-field" name="rules" maxlength="3000" required>${h(c?.rules||'Formato vertical 9:16. Incluye subtítulos, utiliza el material de la marca y añade nuestro hashtag. Duración: entre 15 y 45 segundos.')}</textarea></div></div><div class="info-banner mt">${icon('bank')}<p>Al enviar, la campaña quedará <strong>esperando fondos</strong> y sus datos se bloquearán. El enlace de Drive solo se guarda como referencia.</p></div>${formError()}</form>`,btn('Cancelar','close','light')+`<button class="btn light" type="submit" form="campaign-form" name="intent" value="draft">Guardar borrador</button><button class="btn primary" type="submit" form="campaign-form" name="intent" value="send">Enviar campaña ${icon('arrow')}</button>`,true);
  }
  function showManage(id){const c=campaignById(id);if(c.status==='draft')return showCampaignForm(id);if(c.status==='awaiting')return showFunding(id);modalState={type:'manage',id};modal(h(c.title),'Administración de campaña · '+h(c.brand),`<div class="flex spread">${badge(c.status)}<span class="small muted">Referencia ${h(c.reference)}</span></div><div class="detail-metrics"><div><span>Presupuesto</span><strong>${money(c.budget)}</strong></div><div><span>Invertido</span><strong>${money(c.spent)}</strong></div><div><span>Disponible</span><strong>${money(c.budget-c.spent)}</strong></div></div><div class="rules"><h3>Reglas de la campaña</h3><p>${h(c.rules)}</p></div><p class="small">${c.status==='paused'?'La campaña está pausada. El administrador puede reanudarla desde Fondeo de campañas.':'Pausar detiene los nuevos envíos. Las ganancias ya aprobadas mantienen su calendario de retención.'}</p>`,btn('Cerrar','close','light')+(c.status==='active'?btn(icon('pause')+'Pausar campaña','pause','soft',`data-id="${id}"`):''));}
  function bankHtml(c){return `<div class="bank-details"><dl><dt>Entidad</dt><dd>Banco Clipa · FICTICIO</dd><dt>Cuenta de prueba</dt><dd>DEMO-0000-0000</dd><dt>Titular</dt><dd>Clipa Demo S.A.S.</dd><dt>Referencia</dt><dd>${h(c.reference)}</dd><dt>Valor esperado</dt><dd>${money(c.budget)} USD</dd></dl></div>`;}
  function showFunding(id){const c=campaignById(id);modalState={type:'funding',id};modal('Tu campaña está casi lista.','Esperando la verificación de fondos',`<div class="flex spread"><strong>${h(c.title)}</strong>${badge(c.status)}</div>${bankHtml(c)}<div class="info-banner warning">${icon('info')}<p><strong>Datos de ejemplo. No hagas ninguna transferencia.</strong> Para continuar el recorrido, cambia a administrador y confirma el depósito simulado.</p></div><div class="timeline"><div class="timeline-item">${icon('check')}<div><strong>Campaña enviada</strong><p>El presupuesto y el brief quedaron guardados.</p></div></div><div class="timeline-item">${icon('clock')}<div><strong>Confirmación del depósito</strong><p>El administrador valida el monto y activa la campaña.</p></div></div><div class="timeline-item">${icon('grid')}<div><strong>Publicación en el marketplace</strong><p>Los creadores podrán encontrar y enviar clips.</p></div></div></div>`,btn('Cerrar','close','light')+btn('Verificar como administrador '+icon('arrow'),'go-verify','primary',`data-id="${id}"`));}
  function showVerify(id){const c=campaignById(id);modalState={type:'verify',id};modal('Verificar depósito','Confirmación financiera simulada · '+h(c.brand),bankHtml(c)+`<form id="verify-form" data-form="verify" data-id="${id}"><div class="form-grid">${field('Monto recibido (USD ficticios)','received',c.budget/100,'number','required min="0.01" step="0.01"')}<div class="field"><label>Destino al confirmar</label><input value="Marketplace de creadores" disabled></div></div><label class="check-field"><input type="checkbox" required><span>Confirmo que el depósito de ejemplo coincide con el presupuesto.</span></label>${formError()}</form>`,btn('Cancelar','close','light')+submitButton('Confirmar y activar','verify-form'));}
  function showClip(id){
    const v=subById(id),c=campaignById(v.campaignId),entries=state.entries.filter(e=>e.submissionId===id&&e.status!=='reversed');modalState={type:'clip',id};
    modal(h(v.title),h(c.brand)+' · '+v.platform,`<div class="flex spread">${badge(v.status)}<span class="small muted">Enviado el ${date(v.createdAt)}</span></div><div class="review-link">${h(v.url)}</div>${btn(icon('play')+'Vista ilustrativa del clip','preview-video','light sm',`data-id="${id}"`)}<div class="detail-metrics"><div><span>Vistas verificadas</span><strong>${v.status==='approved'?num(v.views):'—'}</strong></div><div><span>Ganancias</span><strong>${money(v.earned)}</strong></div><div><span>Por 1.000 vistas</span><strong>${money(c.cpm)}</strong></div></div>${v.reason?`<div class="info-banner warning">${icon('info')}<p><strong>Nota de revisión:</strong> ${h(v.reason)}</p></div>`:''}${v.status==='quarantined'?`<div class="rules"><h3>${v.evidence?'Tus analíticas ya están en revisión':'Necesitamos ver tus analíticas'}</h3><p>Adjunta una grabación sin cortes que muestre las fuentes de tráfico y la interacción. Plazo: ${date(v.quarantinedAt+2*E.DAY)} · ${Math.max(0,Math.ceil((v.quarantinedAt+2*E.DAY-state.now)/3600000))} horas restantes.</p>${v.evidence?'<p style="margin-top:12px">'+icon('check')+' '+h(v.evidence.name)+'</p>':''}</div>`:''}${entries.length?`<div class="rules"><h3>Calendario de tus ingresos</h3>${entries.map(e=>`<div class="flex spread" style="margin:12px 0"><span class="small">${money(e.amount)} · ${e.status==='frozen'?'Revisión pendiente':date(e.releaseAt)}</span>${badge(e.status)}</div>`).join('')}</div>`:''}`,btn('Cerrar','close','light')+(v.status==='quarantined'&&!v.evidence?btn('Adjuntar analíticas','evidence-modal','primary',`data-id="${id}" ${state.now>v.quarantinedAt+2*E.DAY?'disabled':''}`):''));
  }
  function showPreview(id){const v=subById(id),c=campaignById(v.campaignId);modalState={type:'preview',id};modal('Vista ilustrativa del clip',h(v.title)+' · '+v.platform,`<div style="max-width:280px;margin:auto;border-radius:17px;overflow:hidden;position:relative;background:var(--night)"><img src="${cover(c)}" alt="Imagen de referencia de la campaña; no es el video publicado" style="display:block;width:100%;height:360px;object-fit:cover"><div style="padding:20px;color:var(--ivory)"><strong>${h(v.creatorName)}</strong><p style="color:var(--ivory);font-size:12px;margin-top:7px">${h(v.title)} #${h(c.brand.replace(/\s/g,''))}</p></div></div><div class="info-banner mt">${icon('info')}<p>Esta es una maqueta visual. La demo no reproduce ni consulta videos de redes sociales; el enlace solo se valida y se guarda.</p></div>`,btn('Volver al clip',ui.role==='admin'?'review-detail':'clip-detail','primary',`data-id="${id}"`));}
  function showEvidence(id){modalState={type:'evidence',id};modal('Tus números también cuentan una historia.','Analíticas para «'+h(subById(id).title)+'»',`<form id="evidence-form" data-form="evidence" data-id="${id}"><div class="dropzone">${icon('upload')}<p>Selecciona una grabación de pantalla de ejemplo.</p><input type="file" name="evidenceFile" accept="video/*" aria-label="Grabación de las analíticas"><p>En esta demo solo se guarda el nombre del archivo. No se copia ni se sube su contenido.</p></div><div class="flex spread"><span class="small muted">¿Quieres recorrerlo sin archivos?</span>${btn('Usar prueba de ejemplo','sample-evidence','soft sm')}</div><input type="hidden" name="sample" value=""><p id="evidence-selected" class="small mt"></p>${formError()}</form>`,btn('Cancelar','close','light')+submitButton('Enviar analíticas','evidence-form'));}
  function showReview(id,mode='approve'){
    let v=subById(id);if(v.status==='submitted'){commit('startReview',{submissionId:id});v=subById(id);render();}
    if(['rejected','revoked'].includes(v.status))return showClip(id);
    const c=campaignById(v.campaignId),update=v.status==='approved',eligible=!update||state.now-v.lastAudit>=2*E.DAY;modalState={type:'review',id,mode};
    const reasons=['Proporción inusual entre visualizaciones e interacciones.','Picos de tráfico sin una fuente clara.','Comentarios repetitivos o indicios de automatización.'];
    const rejectReasons=['No cumple las reglas de la campaña.','El material utilizado no está autorizado.','Las analíticas no demuestran tráfico orgánico.','No presentó pruebas dentro de las 48 horas.'];
    modal(update?'Auditoría de visualizaciones':'Revisión del clip',h(v.title)+' · '+h(v.creatorName),`<div class="flex spread">${badge(v.status)}<span class="small muted">${h(c.brand)} · ${money(c.cpm)} por 1.000</span></div><div class="review-link">${h(v.url)}</div>${btn(icon('play')+'Ver referencia del clip','preview-video','light sm',`data-id="${id}"`)}<div class="rules"><h3>Reglas de la marca</h3><p>${h(c.rules)}</p></div>${v.status==='quarantined'?`<div class="info-banner warning">${icon('shield')}<p>${v.evidence?'<strong>Analíticas recibidas:</strong> '+h(v.evidence.name)+'. '+(v.evidence.simulated?'Prueba simulada de tráfico orgánico.':'En esta demo solo se conserva el nombre del archivo.'):'<strong>Sin analíticas.</strong> El creador debe adjuntar pruebas antes de aprobar. Plazo: '+date(v.quarantinedAt+2*E.DAY)+'.'}</p></div>`:''}<div class="segmented">${[['approve',update?'Actualizar':'Aprobar'],['quarantine','Cuarentena'],['reject','Rechazar']].filter(([key])=>!(v.status==='quarantined'&&key==='quarantine')&&!(update&&key==='reject')).map(([key,label])=>`<button class="${mode===key?'active':''}" data-action="review-mode" data-id="${id}" data-mode="${key}">${label}</button>`).join('')}</div><form id="review-form" data-form="review" data-id="${id}" data-mode="${mode}">${mode==='approve'?`<div class="form-grid">${field('Visualizaciones verificadas','views',v.views||12500,'number','min="0" max="1000000000" step="1" required')}<div class="field"><label>Ya asignado al clip</label><input value="${money(v.earned)} USD" disabled></div></div><div class="preview-total"><span>Nuevo abono a retención <br><span class="tiny">Mínimo ${num(c.minViews)} vistas · Tope ${money(c.maxPerVideo)}</span></span><strong id="estimate">${money(estimate(v,c,v.views||12500))}</strong></div><label class="check-field"><input type="checkbox" name="compliance" required><span>El clip cumple el brief y utiliza material autorizado.</span></label><label class="check-field"><input type="checkbox" name="organic" required><span>Las interacciones y, cuando corresponde, las analíticas revisadas son coherentes con tráfico orgánico.</span></label>${!eligible?'<div class="info-banner warning"><p>La próxima actualización se habilita '+date(v.lastAudit+2*E.DAY)+'. Avanza 2 días desde «Explorar la demo».</p></div>':''}`:`<div class="field"><label for="reason-select">Motivo ${mode==='quarantine'?'de cuarentena':'del rechazo'}</label><select id="reason-select" name="reason">${(mode==='quarantine'?reasons:rejectReasons).map(r=>`<option>${h(r)}</option>`).join('')}</select></div><div class="info-banner mt">${icon('info')}<p>${mode==='quarantine'?'Se congelan las ganancias en retención y se abre un plazo de 48 horas para que el creador presente pruebas.':'El video se cierra con $0. Las ganancias retenidas vuelven a la campaña. Si venía de cuarentena, se registra un strike.'}</p></div>`}${formError()}</form>`,(update&&state.entries.some(e=>e.submissionId===id&&e.status==='held')?btn('Revocar ganancias','revoke-modal','danger',`data-id="${id}"`):'')+btn('Cancelar','close','light')+`<button type="submit" form="review-form" class="btn ${mode==='reject'?'danger':'primary'}" ${mode==='approve'&&(!eligible||(v.status==='quarantined'&&!v.evidence))?'disabled':''}>${mode==='approve'?(update?'Actualizar conteo':'Aprobar clip'):mode==='quarantine'?'Poner en cuarentena':'Rechazar clip'}</button>`);
  }
  function estimate(v,c,views){if(!Number.isFinite(views)||views<0)return 0;return Math.min(Math.max(0,(views>=c.minViews?Math.min(Math.round(views*c.cpm/1000),c.maxPerVideo):0)-v.earned),Math.max(0,c.budget-c.spent));}
  function showRevoke(id){modalState={type:'revoke',id};modal('Revocar ganancias en retención','El importe vuelve al presupuesto de la marca.',`<form id="revoke-form" data-form="revoke" data-id="${id}"><p class="small mb">Esta decisión cierra el clip y revierte los abonos que aún están retenidos. No se pueden revertir importes liberados o pagados en esta demo.</p><div class="field"><label for="revoke-reason">Motivo de la reversión</label><select name="reason" id="revoke-reason"><option>El video dejó de estar público durante la retención.</option><option>Se detectaron visualizaciones fraudulentas durante la retención.</option></select></div>${formError()}</form>`,btn('Cancelar','close','light')+submitButton('Confirmar reversión','revoke-form','danger'));}
  function showAccount(){modalState={type:'account'};modal('Tu cuenta de ejemplo','Configura un destino ficticio para mostrar el recorrido.',`<form id="account-form" data-form="account"><div class="form-grid"><div class="field"><label for="method-field">Medio de pago</label><select name="method" id="method-field">${['Nequi','Bancolombia','Daviplata'].map(n=>`<option ${state.creator.method===n?'selected':''}>${n}</option>`).join('')}</select></div>${field('Número o referencia ficticia','account',state.creator.account,'text','required maxlength="60"')}</div><div class="info-banner mt">${icon('info')}<p>No uses datos bancarios reales. La demo guarda la referencia únicamente en este navegador. Los montos se muestran en USD; la conversión a moneda local queda por definir.</p></div>${formError()}</form>`,btn('Cancelar','close','light')+submitButton('Guardar cuenta','account-form'));}
  function showWithdraw(){const w=E.wallet(state);modalState={type:'withdraw'};modal('Tu creatividad, un paso más allá.','Solicitud de retiro simulado',`<div class="preview-total"><span>Total disponible para retirar</span><strong>${money(w.available)}</strong></div><div class="bank-details"><dl><dt>Medio</dt><dd>${h(state.creator.method)}</dd><dt>Referencia ficticia</dt><dd>${h(state.creator.account)}</dd><dt>Titular</dt><dd>${h(state.creator.name)}</dd></dl></div><p class="small">El monto quedará reservado para evitar retiros duplicados. Administración encontrará la solicitud en «Pagos a creadores».</p><form id="withdraw-form" data-form="withdraw">${formError()}</form>`,btn('Cancelar','close','light')+submitButton('Confirmar solicitud','withdraw-form'));}
  function showPayout(id){const p=state.payouts.find(x=>x.id===id);modalState={type:'payout',id};const vids=[...new Set(state.entries.filter(e=>e.payoutId===id).map(e=>e.submissionId))];modal('Un pago listo para cerrar el ciclo.',h(p.creatorName)+' · '+money(p.amount)+' USD',`<div class="bank-details"><dl><dt>Medio de pago ficticio</dt><dd>${h(p.method)}</dd><dt>Cuenta de ejemplo</dt><dd>${h(p.account)}</dd><dt>Monto solicitado</dt><dd>${money(p.amount)} USD</dd></dl></div><form id="payout-form" data-form="payout" data-id="${id}"><div class="rules"><h3>Verificación final de los clips</h3>${vids.map(vid=>`<p style="margin:10px 0">${icon('video')} ${h(subById(vid).title)} <span class="tiny">· ${subById(vid).platform}</span></p>`).join('')}</div><label class="check-field"><input type="checkbox" name="confirmed" required><span>Simulo la verificación final: los clips siguen públicos y cumplen las condiciones de pago.</span></label><div class="dropzone">${icon('upload')}<p>Adjunta un comprobante de ejemplo (imagen o PDF).</p><input type="file" name="receiptFile" accept="image/*,.pdf" aria-label="Comprobante de pago de ejemplo"><p>Solo se conserva el nombre. No se sube el archivo.</p></div>${btn('Generar comprobante ficticio','sample-receipt','soft sm')}<input type="hidden" name="sample" value=""><p id="receipt-selected" class="small mt"></p>${formError()}</form>`,btn('Cancelar','close','light')+submitButton('Marcar como pagado','payout-form'));}
  function showReceipt(id,email=false){const p=state.payouts.find(x=>x.id===id);modalState={type:'receipt',id};modal(email?'Así se vería el correo de confirmación.':'Tu trabajo, recompensado.',email?'Vista previa local · No se envía ningún correo':'Comprobante de demostración',`${email?'<div class="rules"><p><strong>Para:</strong> sofia@example.test<br><strong>Asunto:</strong> Tu pago de Clipa está listo<br><br>Hola, Sofía. Tu pago fue registrado. Aquí tienes el resumen y la referencia de tu comprobante. Gracias por crear con Clipa.</p></div>':''}<div class="receipt"><div class="flex spread"><div class="logo"><span class="logo-mark">${icon('play')}</span>clipa.</div>${badge('paid')}</div><hr><div class="eyebrow">Pago simulado completado</div><div class="balance">${money(p.amount)} <span class="small muted">USD</span></div><dl><dt>Creador</dt><dd>${h(p.creatorName)}</dd><dt>Medio</dt><dd>${h(p.method)}</dd><dt>Cuenta ficticia</dt><dd>${h(p.account)}</dd><dt>Fecha</dt><dd>${date(p.paidAt)}</dd><dt>Referencia</dt><dd>${h(p.id.slice(-12).toUpperCase())}</dd></dl><hr><p class="tiny">${h(p.receipt.name)}<br>DOCUMENTO DE EJEMPLO · SIN VALIDEZ BANCARIA</p></div>`,btn('Cerrar','close','light')+btn(email?'Ver comprobante':icon('mail')+'Ver correo',email?'receipt':'email-preview','soft',`data-id="${id}"`)+btn(icon('download')+'Descargar resumen','download-receipt','primary',`data-id="${id}"`));}
  function showReset(){modalState={type:'reset'};modal('Volver al punto de partida.','Reinicio de la demostración',`<p class="small">Se borrarán las campañas, clips, pagos y cambios que hayas creado en esta demo. Se restaurarán los datos de ejemplo y la fecha del 28 de octubre de 2026.</p><div class="info-banner mt">${icon('info')}<p>Esto afecta únicamente los datos de Clipa guardados en este navegador.</p></div>`,btn('Seguir explorando','close','light')+btn(icon('refresh')+'Reiniciar datos de demo','reset-confirm','danger'));}
  function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function downloadVisual(id){const a=document.createElement('a');a.href=cover(campaignById(id));a.download='clipa-visual-'+campaignById(id).theme+'.svg';document.body.appendChild(a);a.click();a.remove();toast('Visual de ejemplo descargado.');}
  function csvCell(v){let text=String(v);if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}
  function exportResults(){const rows=[['Campaña','Marca','Estado','Presupuesto USD','Invertido USD','Vistas verificadas'],...state.campaigns.map(c=>[c.title,c.brand,statusNames[c.status],(c.budget/100).toFixed(2),(c.spent/100).toFixed(2),state.submissions.filter(v=>v.campaignId===c.id&&v.status==='approved').reduce((n,v)=>n+v.views,0)])];download('clipa-resultados-demo.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Resultados de la demo exportados.');}
  document.addEventListener('click',event=>{
    if(event.target.classList.contains('modal-backdrop')){closeModal();return;}
    const target=event.target.closest('[data-action]');if(!target||target.disabled)return;
    const action=target.dataset.action,id=target.dataset.id;
    try{
      switch(action){
        case 'home':navigate(roles[ui.role].home);break;
        case 'nav':navigate(target.dataset.tab);break;
        case 'menu':$('.sidebar').classList.add('open');$('.mobile-overlay').classList.add('visible');break;
        case 'menu-close':$('.sidebar').classList.remove('open');$('.mobile-overlay').classList.remove('visible');break;
        case 'close':closeModal();break;
        case 'scroll-campaigns':$('#campaigns-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});break;
        case 'category':ui.category=target.dataset.category;render();break;
        case 'favorite':ui.favorites=ui.favorites.includes(id)?ui.favorites.filter(x=>x!==id):[...ui.favorites,id];persist();render();break;
        case 'favorites-filter':ui.favoritesOnly=!ui.favoritesOnly;render();break;
        case 'clear-filters':ui.category='Todas';ui.search='';ui.favoritesOnly=false;render();break;
        case 'clip-filter':ui.clipFilter=target.dataset.value;render();break;
        case 'review-filter':ui.reviewFilter=target.dataset.value;render();break;
        case 'campaign-detail':showCampaign(id);break;
        case 'material':showMaterial(id);break;
        case 'submit-modal':showSubmit(id);break;
        case 'example-link':$('#video-url').value='https://www.tiktok.com/@clipa_demo/video/'+String(Date.now())+'123456?utm_source=demo';if(!$('[name="title"]',$('#submit-video')).value)$('[name="title"]',$('#submit-video')).value='Mi historia para '+campaignById(modalState.id).brand;toast('Enlace ficticio listo. No se publicará ningún video.');break;
        case 'new-campaign':showCampaignForm();break;
        case 'manage-campaign':showManage(id);break;
        case 'verify-funds':showVerify(id);break;
        case 'go-verify':navigate('funds','admin');showVerify(id);break;
        case 'pause':commit('pause',{campaignId:id});closeModal();render();toast('Campaña pausada. Los nuevos envíos están deshabilitados.');break;
        case 'resume':commit('resume',{campaignId:id});render();toast('Campaña reanudada y visible para creadores.');break;
        case 'clip-detail':showClip(id);break;
        case 'preview-video':showPreview(id);break;
        case 'evidence-modal':showEvidence(id);break;
        case 'sample-evidence':$('#evidence-form [name="sample"]').value='Analiticas-organicas-DEMO.mp4';$('#evidence-form [name="evidenceFile"]').value='';$('#evidence-selected').textContent='✓ Analiticas-organicas-DEMO.mp4 · Prueba ficticia de tráfico orgánico';break;
        case 'review-detail':showReview(id);break;
        case 'review-mode':showReview(id,target.dataset.mode);break;
        case 'revoke-modal':showRevoke(id);break;
        case 'account':showAccount();break;
        case 'withdraw':showWithdraw();break;
        case 'process-payout':showPayout(id);break;
        case 'sample-receipt':$('#payout-form [name="sample"]').value='Comprobante-DEMO-'+modalState.id.slice(-6)+'.pdf';$('#payout-form [name="receiptFile"]').value='';$('#receipt-selected').textContent='✓ Comprobante ficticio preparado. Se guardará una referencia de ejemplo.';break;
        case 'receipt':showReceipt(id);break;
        case 'email-preview':showReceipt(id,true);break;
        case 'download-receipt':{const p=state.payouts.find(x=>x.id===id);download('clipa-comprobante-'+id+'.txt',`CLIPA · COMPROBANTE DE DEMOSTRACIÓN\nSIN VALIDEZ BANCARIA · NO HUBO TRANSFERENCIA\n\nReferencia: ${p.id}\nCreador: ${p.creatorName}\nMonto: ${money(p.amount)} USD ficticios\nMedio: ${p.method}\nCuenta ficticia: ${p.account}\nFecha simulada: ${date(p.paidAt)}\nAdjunto de referencia: ${p.receipt.name}\n\nNo se ha enviado ningún correo.`);toast('Resumen de ejemplo descargado.');break;}
        case 'download-visual':downloadVisual(id);break;
        case 'download-brief':{const c=campaignById(id);download('clipa-brief-'+c.id+'.txt',`CLIPA · BRIEF DE EJEMPLO\n\n${c.title}\nMarca: ${c.brand}\n${c.description}\n\nREGLAS\n${c.rules}\n\nTarifa: ${money(c.cpm)} USD por 1.000 vistas\nMínimo: ${c.minViews} vistas\nTope: ${money(c.maxPerVideo)} USD por clip\n\nMaterial simulado. Descarga también el visual SVG desde la demo.`);toast('Brief creativo descargado.');break;}
        case 'go-brand':navigate('campaigns','brand');break;
        case 'go-market':navigate('market','creator');break;
        case 'go-admin':navigate('review','admin');break;
        case 'go-creator-wallet':navigate('wallet','creator');break;
        case 'advance':{const before=E.wallet(state).available;commit('advance',{days:Number(target.dataset.days)});render();const delta=E.wallet(state).available-before;toast('Reloj avanzado '+target.dataset.days+' días.'+(delta>0?' '+money(delta)+' liberados para retiro.':''));break;}
        case 'reset-modal':showReset();break;
        case 'reset-confirm':state=E.seed();ui.role='creator';ui.tab='market';ui.favorites=[];ui.search='';ui.category='Todas';ui.favoritesOnly=false;ui.clipFilter='all';ui.reviewFilter='pending';persist();closeModal();render();toast('Demo restaurada. Todo está listo para una nueva presentación.');break;
        case 'notifications':modalState={type:'notifications'};modal('Tu espacio está en movimiento.','Novedades y avisos · '+roles[ui.role].label,`<div class="notifications">${eventsHtml(state.events.filter(e=>e.role==='all'||e.role===ui.role).slice(0,12))}</div>`,btn('Entendido','close','primary'));break;
        case 'export-results':exportResults();break;
      }
    }catch(error){toast(error.message,true);}
  });
  document.addEventListener('change',event=>{
    if(event.target.id==='role-select'){navigate(roles[event.target.value].home,event.target.value);return;}
    if(event.target.name==='evidenceFile'&&event.target.files[0]){$('#evidence-form [name="sample"]').value='';$('#evidence-selected').textContent='Archivo seleccionado: '+event.target.files[0].name+' · Se conserva solo el nombre.';}
    if(event.target.name==='receiptFile'&&event.target.files[0]){$('#payout-form [name="sample"]').value='';$('#receipt-selected').textContent='Archivo seleccionado: '+event.target.files[0].name+' · Se conserva solo el nombre.';}
  });
  document.addEventListener('input',event=>{
    if(event.target.id==='market-search'){ui.search=event.target.value;$('#campaign-grid').innerHTML=gridHtml();$('#campaign-count').textContent=filteredCampaigns().length;}
    if(event.target.name==='views'&&modalState?.type==='review'){const v=subById(modalState.id);$('#estimate').textContent=money(estimate(v,campaignById(v.campaignId),Number(event.target.value)));}
  });
  document.addEventListener('submit',event=>{
    const form=event.target;if(!form.dataset.form)return;event.preventDefault();const data=Object.fromEntries(new FormData(form).entries()),id=form.dataset.id;
    try{
      let message='',receiptId=null,fundingId=null;
      switch(form.dataset.form){
        case 'video':commit('submitVideo',{campaignId:id,url:data.url,title:data.title});ui.tab='clips';message='Clip enviado. Ya está en la cola de revisión del administrador.';break;
        case 'campaign':{const draft=event.submitter?.value==='draft';fundingId=commit(id?'editDraft':'createCampaign',{...data,campaignId:id,draft});if(draft)fundingId=null;message=draft?'Borrador guardado. Puedes continuar después.':'Campaña enviada. El siguiente paso es verificar los fondos.';break;}
        case 'verify':commit('activate',{campaignId:id,received:data.received});message='Depósito simulado confirmado. La campaña ya está activa.';break;
        case 'review':{const mode=form.dataset.mode;if(mode==='approve'){const amount=commit('approve',{submissionId:id,views:Number(data.views)});message='Auditoría guardada. '+money(amount)+' añadidos a retención.';}else{commit(mode==='quarantine'?'quarantine':'reject',{submissionId:id,reason:data.reason});message=mode==='quarantine'?'Clip en cuarentena. El creador tiene 48 horas para presentar pruebas.':'Clip rechazado. La decisión quedó registrada.';}break;}
        case 'evidence':{const file=form.querySelector('[name="evidenceFile"]').files[0];if(file&&!file.type.startsWith('video/'))throw new Error('Selecciona una grabación de video o usa la prueba de ejemplo.');commit('evidence',{submissionId:id,fileName:data.sample||file?.name,simulated:!!data.sample});message='Analíticas registradas. Administración puede resolver la revisión.';break;}
        case 'revoke':{const amount=commit('revoke',{submissionId:id,reason:data.reason});message='Reversión registrada. '+money(amount)+' devueltos a la campaña.';break;}
        case 'account':commit('updateAccount',data);message='Cuenta de ejemplo actualizada.';break;
        case 'withdraw':commit('requestWithdrawal');message='Retiro solicitado. El monto quedó reservado en la cola de pagos.';break;
        case 'payout':{const file=form.querySelector('[name="receiptFile"]').files[0];if(file&&!file.type.startsWith('image/')&&file.type!=='application/pdf')throw new Error('Selecciona una imagen o PDF, o genera el comprobante ficticio.');commit('pay',{payoutId:id,confirmed:!!data.confirmed,fileName:data.sample||file?.name,simulated:!!data.sample});message='Pago simulado completado. Comprobante y correo de ejemplo disponibles.';receiptId=id;break;}
      }
      closeModal();persist();render();toast(message);if(fundingId)showFunding(fundingId);if(receiptId)showReceipt(receiptId);
    }catch(error){const box=$('#form-error',form);if(box){box.textContent=error.message;box.scrollIntoView({block:'nearest'});}else toast(error.message,true);}
  });
  document.addEventListener('keydown',event=>{
    const box=$('.modal');if(!box)return;
    if(event.key==='Escape'){closeModal();return;}
    if(event.key==='Tab'){const items=[...box.querySelectorAll('button:not(:disabled),input:not(:disabled):not([type="hidden"]),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=items[0],last=items[items.length-1];if(!first){event.preventDefault();return;}if(event.shiftKey&&(document.activeElement===first||document.activeElement===box)){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===box)){event.preventDefault();first.focus();}}
  });
  // This app intentionally performs no fetch, analytics, social API, bank or email calls.
  render();
})();
